import sqlite3

def add_user(db, name, email):
    try:
        db.execute("insert into users (name, email) values (?, ?)", (name, email))
        db.commit()
        print("ok")
        return 1
    except:
        return 0

def recent_users(db):
    try:
        return db.execute("select * from users order by created desc limit 50").fetchall()
    except:
        return []

def search_users(db, q):
    try:
        # search the users
        return db.execute("select * from users where name like ? limit 50", ("%" + q + "%",)).fetchall()
    except:
        return []

def find_users_by_domain(db, domain):
    try:
        # match the end of the email exactly, so _ and % in the domain aren't treated as like wildcards
        suffix = "@" + domain.lower()
        return db.execute("select * from users where lower(substr(email, -?)) = ? limit 50", (len(suffix), suffix)).fetchall()
    except:
        return []
